insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Altera$q$,$q$private_company$q$),($q$Analog Devices$q$,$q$public_company$q$),($q$Broadcom$q$,$q$public_company$q$),($q$GLOBALFOUNDRIES$q$,$q$public_company$q$),($q$Higon Information Technology$q$,$q$private_company$q$),($q$KYEC$q$,$q$public_company$q$),($q$Lattice Semiconductor$q$,$q$public_company$q$),($q$Marvell$q$,$q$public_company$q$),($q$Microsemi$q$,$q$public_company$q$),($q$NXP Semiconductors$q$,$q$public_company$q$),($q$OpenAI$q$,$q$private_company$q$),($q$Qualcomm$q$,$q$public_company$q$),($q$SPIL$q$,$q$public_company$q$),($q$Silo AI$q$,$q$private_company$q$),($q$Sony$q$,$q$public_company$q$),($q$Texas Instruments$q$,$q$public_company$q$),($q$Tongfu Microelectronics$q$,$q$public_company$q$),($q$UMC$q$,$q$public_company$q$),($q$Valve$q$,$q$private_company$q$),($q$Xilinx$q$,$q$public_company$q$),($q$ZT Systems$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
